from functools import lru_cache


def count_upto(n, k, r):
    if n < 0:
        return 0
    digits = list(map(int, str(n)))

    @lru_cache(None)
    def dp(pos, tight, started, last, residue):
        if pos == len(digits):
            # The not-started path represents the integer 0.
            return int(residue == r)
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            next_tight = tight and (d == limit)
            if not started and d == 0:
                total += dp(pos + 1, next_tight, False, 10, residue)
            elif started and d == last:
                continue
            else:
                total += dp(pos + 1, next_tight, True, d, (residue + d) % k)
        return total

    return dp(0, True, False, 10, 0)


def main():
    L, R, k, r = map(int, sys.stdin.buffer.read().split())
    print(count_upto(R, k, r) - count_upto(L - 1, k, r))


if __name__ == '__main__':
    main()
